+		return {
+			extensions,
+			pluginPaths: selected.map(({ entry }) => entry.pluginPath),
+			failures,
+			warnings,
+			issues,
+			release: () => {
+				released ??= Promise.all(
+					selected.map(({ entry, instance }) =>
+						this.releaseInstance(entry, instance, sessionId, timeouts),
+					),
+				).then(() => undefined);
+				return released;
+			},
+		};
+	}
+
+	/**
